using Microsoft.Extensions.AI;
using System.ComponentModel;
using System.Text.Json;

Console.WriteLine("Research Agent Starting...");
Console.WriteLine("=========================\n");

string topic = args.Length > 0 ? string.Join(' ', args) : "the impact of artificial intelligence on healthcare";
Console.WriteLine($"Researching topic: {topic}\n");

// Configure the AI chat client with tool support
var endpoint = Environment.GetEnvironmentVariable("OPENAI_ENDPOINT") ?? "https://api.openai.com/v1";
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "";
var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

if (string.IsNullOrEmpty(apiKey))
{
    Console.WriteLine("Error: Set the OPENAI_API_KEY environment variable.");
    return;
}

var openAiClient = new OpenAI.OpenAIClient(apiKey);
IChatClient innerClient = openAiClient.GetChatClient(modelId).AsIChatClient();

// Create tools
var researchTools = new ResearchTools();

IChatClient agent = new ChatClientBuilder(innerClient)
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions
{
    Tools = [
        AIFunctionFactory.Create(researchTools.SearchWeb),
        AIFunctionFactory.Create(researchTools.TakeNote),
        AIFunctionFactory.Create(researchTools.GetNotes),
    ]
};

var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your job is to research a given topic thoroughly.

        Follow these steps:
        1. Search the web for information about the topic (perform 2-3 searches with different queries)
        2. Take notes on the key findings from each search
        3. Review your notes and provide a comprehensive summary

        Always use the tools available to you. Take notes as you discover information.
        End with a final summary of your research findings.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a summary: {topic}")
};

Console.WriteLine("Agent is researching...\n");

// Run the agent loop
var response = await agent.GetResponseAsync(messages, chatOptions);

Console.WriteLine("\n--- Agent Response ---\n");
Console.WriteLine(response.Text);

Console.WriteLine("\n\n--- Collected Notes ---");
foreach (var note in researchTools.Notes)
{
    Console.WriteLine($"  • {note}");
}

Console.WriteLine("\nResearch complete.");

// --- Tool Definitions ---

public class ResearchTools
{
    public List<string> Notes { get; } = [];

    [Description("Search the web for information on a query. Returns relevant search results.")]
    public string SearchWeb([Description("The search query")] string query)
    {
        Console.WriteLine($"  [Tool] Searching web for: \"{query}\"");

        // Simulated web search results for demonstration
        var results = GenerateSearchResults(query);
        return JsonSerializer.Serialize(new { query, results });
    }

    [Description("Take a note to remember important information found during research.")]
    public string TakeNote([Description("The note content to save")] string note)
    {
        Notes.Add(note);
        Console.WriteLine($"  [Tool] Note taken: \"{note[..Math.Min(note.Length, 60)]}...\"");
        return $"Note saved successfully. Total notes: {Notes.Count}";
    }

    [Description("Retrieve all notes taken so far during the research session.")]
    public string GetNotes()
    {
        Console.WriteLine("  [Tool] Retrieving all notes...");
        if (Notes.Count == 0)
            return "No notes taken yet.";

        return JsonSerializer.Serialize(Notes.Select((n, i) => new { index = i + 1, content = n }));
    }

    private static List<object> GenerateSearchResults(string query)
    {
        // Simulated search results based on query keywords
        var results = new List<object>();
        var queryLower = query.ToLowerInvariant();

        if (queryLower.Contains("ai") || queryLower.Contains("artificial intelligence"))
        {
            results.Add(new { title = "AI in Modern Healthcare - Nature Review", snippet = "Artificial intelligence is transforming diagnostics, drug discovery, and personalized medicine. Machine learning models now achieve radiologist-level accuracy in imaging analysis." });
            results.Add(new { title = "WHO Report on AI in Health", snippet = "The WHO recommends ethical frameworks for AI deployment in healthcare, emphasizing transparency, equity, and human oversight in clinical decision-making." });
            results.Add(new { title = "AI-Powered Drug Discovery - Science Daily", snippet = "Recent breakthroughs show AI reducing drug discovery timelines from years to months, with several AI-discovered compounds entering clinical trials in 2025." });
        }
        else if (queryLower.Contains("healthcare") || queryLower.Contains("medical"))
        {
            results.Add(new { title = "Digital Health Transformation 2026", snippet = "Telemedicine, wearable devices, and AI-assisted diagnostics are reshaping patient care delivery worldwide, with adoption rates tripling since 2023." });
            results.Add(new { title = "Electronic Health Records and AI", snippet = "Integration of AI with EHR systems enables predictive analytics for patient outcomes, reducing hospital readmission rates by up to 25%." });
        }
        else if (queryLower.Contains("ethics") || queryLower.Contains("challenges") || queryLower.Contains("risks"))
        {
            results.Add(new { title = "Ethical Challenges of AI in Medicine", snippet = "Key concerns include algorithmic bias in clinical datasets, patient privacy with large-scale data collection, and accountability when AI systems make errors." });
            results.Add(new { title = "Regulatory Frameworks for Health AI", snippet = "The FDA has approved over 500 AI-based medical devices, but experts call for more rigorous post-market surveillance and bias auditing requirements." });
        }
        else
        {
            results.Add(new { title = $"Research findings on: {query}", snippet = $"Multiple studies explore various aspects of {query}, highlighting both opportunities and challenges in the field." });
            results.Add(new { title = $"Recent developments in {query}", snippet = $"The landscape of {query} continues to evolve rapidly with new breakthroughs and applications emerging regularly." });
        }

        return results;
    }
}

